import numpy as np

raw = pd.read_csv('raw_responses.csv')
out = pd.read_csv('pipeline_output.csv')

def clean_val(x):
    # any number not in 0,1,2,3 is missing (-9, etc.)
    try:
        val = int(x)
        if val in [0, 1, 2, 3]:
            return val
    except:
        pass
    return np.nan

# PHQ-9 items
phq9_cols = [f'phq9_{i}' for i in range(1, 10)]
gad7_cols = [f'gad7_{i}' for i in range(1, 8)]
rses_cols = [f'rses_{i}' for i in range(1, 11)]

# Let's check PHQ-9 scoring
def score_phq9(row):
    vals = [clean_val(row[c]) for c in phq9_cols]
    n_missing = sum(pd.isna(vals))

    # self harm flag based on phq9_9
    v9 = clean_val(row['phq9_9'])
    if pd.isna(v9):
        sh_flag = np.nan
    else:
        sh_flag = (v9 > 0)

    if n_missing >= 2:
        return np.nan, np.nan, np.nan, sh_flag
    elif n_missing == 1:
        valid_vals = [v for v in vals if not pd.isna(v)]
        total = round(sum(valid_vals) * 9 / 8) # Python round uses round-to-even, let's check how halves are rounded: "Halves always round up, so 4.5 becomes 5"
        # Wait, Python 3 round(4.5) is 4 (round half to even). The guide says: "Halves always round up, so 4.5 becomes 5 and 10.5 becomes 11."
        prorated = True
    else:
        total = int(sum(vals))
        prorated = False

    # band
    if pd.isna(total):
        band = np.nan
    else:
        if total <= 4:
            band = 'none-minimal' # Wait, let's check exact string used in pipeline or guide
        elif total <= 9:
            band = 'mild'
        elif total <= 14:
            band = 'moderate'
        elif total <= 19:
            band = 'moderately severe'
        else:
            band = 'severe'

    return total, band, prorated, sh_flag

# Let's test rounding function for halves: standard python round(2.5) -> 2. In decimal, 2.5 should be 3.
# Let's check how math.floor(x + 0.5) or decimal module works.
from decimal import Decimal, ROUND_HALF_UP

def round_half_up(val):
    return int(Decimal(str(val)).quantize(Decimal('1'), rounding=ROUND_HALF_UP))

print("round_half_up(4.5):", round_half_up(4.5))
print("round_half_up(10.5):", round_half_up(10.5))
